local PLAY_INTRO, BUILD_CREDITS
do
local GREEN = Color3.fromRGB(0, 255, 127)
local DARK = Color3.fromRGB(18, 18, 25)
local ACCENT = Color3.fromRGB(0, 230, 118)
local SCRIPT_NAME = "ACTOP"
local INTRO_TIME = 11.9         -- مدة المقدمة بالثواني (طول صوت تانجيرو)
local LocalPlayer = game:GetService("Players").LocalPlayer
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local LoadPic, PIC_CACHE
local function mountGui(gui)
    local ok = pcall(function()
        gui.Parent = (gethui and gethui()) or game:GetService("CoreGui")
    end)
    if not ok or not gui.Parent then
        gui.Parent = LocalPlayer:WaitForChild("PlayerGui")
    end
end

local function tween(obj, time, props, style)
    local t = TweenService:Create(obj, TweenInfo.new(time, style or Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props)
    t:Play()
    return t
end


local function corner(o, r)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, r)
    c.Parent = o
    return c
end

