-- فك تشفير base64 (يستخدم دالة الاكسكيوتر لو موجودة، وإلا نسخة Lua)
local B64CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64LOOK = {}
for i = 1, 64 do B64LOOK[B64CHARS:byte(i)] = i - 1 end

local function luaB64Decode(s)
    s = s:gsub("[^%w%+/=]", "")
    local out, n = {}, 0
    for i = 1, #s, 4 do
        local c1, c2, c3, c4 = s:byte(i, i + 3)
        local v = (B64LOOK[c1] or 0) * 262144 + (B64LOOK[c2] or 0) * 4096
            + (B64LOOK[c3] or 0) * 64 + (B64LOOK[c4] or 0)
        local b1, b2, b3 = math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256
        if c4 == 61 then
            if c3 == 61 then out[#out + 1] = string.char(b1)
            else out[#out + 1] = string.char(b1, b2) end
        else
            out[#out + 1] = string.char(b1, b2, b3)
        end
        n += 1
        if n % 20000 == 0 then task.wait() end
    end
    return table.concat(out)
end

local function getB64Decoder()
    local candidates = {
        function() return crypt.base64decode end,
        function() return crypt.base64.decode end,
        function() return syn.crypt.base64.decode end,
        function() return base64_decode end,
        function() return base64.decode end,
    }
    for _, get in ipairs(candidates) do
        local ok, f = pcall(get)
        if ok and type(f) == "function" then
            local ok2, res = pcall(f, "QQ==")
            if ok2 and res == "A" then return f end
        end
    end
    return luaB64Decode
end

local function LoadIntroAssets()
    local getasset = getcustomasset or getsynasset
    if not (writefile and isfile and getasset) then return nil end
    local decode = getB64Decoder()

    local function prep(name, b64)
        local ok, asset = pcall(function()
            local need = true
            if isfile(name) and readfile then
                local okr, data = pcall(readfile, name)
                need = not (okr and data and #data > 500)
            end
            if need then writefile(name, decode(b64)) end
            return getasset(name)
        end)
        if ok then return asset end
        return nil
    end

    return {
        pic = prep("ACTOP_777_v1.jpg", ASSET_PIC),
        audio = prep("ACTOP_voice_v2.mp3", ASSET_AUDIO),
        gif = prep("ACTOP_gif_v6.jpg", ASSET_GIF),
    }
end

