        if sound then sound.Volume = muted and 0 or 1 end
        muteBtn.Text = muted and "🔊 تشغيل الصوت" or "🔇 كتم الصوت"
    end)

    local function easeBack(p)
        local c1, c3 = 1.70158, 2.70158
        return 1 + c3 * (p - 1) ^ 3 + c1 * (p - 1) ^ 2
    end

    tween(fade, 0.5, {BackgroundTransparency = 1})
    if sound then pcall(function() sound:Play() end) end

    local start = os.clock()
    conn = RunService.RenderStepped:Connect(function()
        local t = os.clock() - start
        if t >= INTRO_TIME then finish() return end

        -- ظهور بنطّة + طفو خفيف + نبض
        local p = math.min(t / 0.7, 1)
        local pop = easeBack(p)
        ava.Position = UDim2.new(0.2, 0, 0.46 + 0.012 * math.sin(t * 2.4), 0)
        ava.Rotation = 2.5 * math.sin(t * 1.6)
        avaScale.Scale = pop * (1 + 0.035 * math.sin(t * 3.2))

        -- حلقة تدور + موجات
        rg.Rotation = (t * 160) % 360
        for i, w in ipairs(waves) do
            local ph = ((t * 0.9) + (i - 1) * 0.5) % 1
            w.scale.Scale = 1 + 0.3 * ph
            w.stroke.Transparency = 0.2 + 0.8 * ph
        end

        -- الجيف: تبديل الفريمات
        if gifImg then
            local idx = math.floor(t / GIF_DT) % GIF_N
            gifImg.ImageRectOffset = Vector2.new((idx % GIF_COLS) * GIF_FW, math.floor(idx / GIF_COLS) * GIF_FH)
        end

        -- شريط التقدم
        bar.Size = UDim2.new(math.min(t / INTRO_TIME, 1), 0, 1, 0)
    end)

    while not finished do
        task.wait(0.05)
    end

    -- خروج بنعومة
    tween(fade, 0.45, {BackgroundTransparency = 0})
    task.wait(0.5)
    gui:Destroy()
end



