local function isWelded(handle)
for _, d in ipairs(handle:GetChildren()) do
if d:IsA("Weld") or d:IsA("WeldConstraint") or d:IsA("Motor6D") then
return true
end
end
return false
end
local function attachAccessory(char, h, acc)
pcall(function()
h:AddAccessory(acc)
end)
if acc.Parent ~= char then
acc.Parent = char
end
local handle = acc:FindFirstChild("Handle")
if not handle or not handle:IsA("BasePart") then
return false
end
if isWelded(handle) then
return true
end
handle.CanCollide = false
handle.Massless = true
local att = handle:FindFirstChildOfClass("Attachment")
local target = nil
if att then
for _, part in ipairs(char:GetChildren()) do
if part:IsA("BasePart") then
local a = part:FindFirstChild(att.Name)
if a and a:IsA("Attachment") then
target = a
break
end
end
end
end
local head = char:FindFirstChild("Head")
if target then
handle.CFrame = target.WorldCFrame * att.CFrame:Inverse()
local w = Instance.new("Weld")
w.Part0 = target.Parent
w.Part1 = handle
w.C0 = target.CFrame
w.C1 = att.CFrame
w.Parent = handle
return true
elseif head then
handle.CFrame = head.CFrame * CFrame.new(0, head.Size.Y / 2, 0)
local w = Instance.new("WeldConstraint")
w.Part0 = head
w.Part1 = handle
w.Parent = handle
return true
end
return false
end
local LEG_X, LEG_TOP = 0.5, -1.0
