d:Destroy()
end
end
c.Name = "KX_" .. n
c.Anchored = false
c.CanCollide = false
c.CanTouch = false
c.CanQuery = false
c.Massless = true
c.Transparency = 0
c.CFrame = dst.CFrame
local w = Instance.new("WeldConstraint")
w.Part0 = dst
w.Part1 = c
w.Parent = c
c.Parent = char
table.insert(fakeLegParts, c)
made = made + 1
end
end
pcall(function()
dummy:Destroy()
end)
return made > 0
end
