piece(Vector3.new(sx * 0.12, sy * 0.38, sz * 0.12), CFrame.new(math.cos(ang) * sx * 0.5, sy * 0.88, math.sin(ang) * sz * 0.5), Color3.fromRGB(35, 38, 48))
